{"items":[{"path":"tools.github.issue_read","description":"Get information about a specific issue in a GitHub repository.","signature":"tools.github.issue_read({
  /** The number of the issue */
  issue_number: number,
  /**
   * The read operation to perform on a single issue.
   * Options are:
   * 1. get - Get issue details. Also returns best-effort hierarchy flags (`has_parent`, `has_children`); `parent` and `sub_issues_summary` are optional relationship summaries, and `closed_by_pull_requests` summarizes the pull requests configured to close the issue as `total_count` plus up to 5 `references`.
   * 2. get_comments - Get issue comments.
   * 3. get_sub_issues - Get sub-issues (children) of the issue.
   * 4. get_parent - Get the parent issue, if this issue is a sub-issue of another.
   * 5. get_labels - Get labels assigned to the issue.
   */
  method: "get" | "get_comments" | "get_sub_issues" | "get_parent" | "get_labels",
  /** The owner of the repository */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** The name of the repository */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.issue_write","description":"Create a new or update an existing issue in a GitHub repository.","signature":"tools.github.issue_write({
  /** Usernames to assign to this issue */
  assignees?: Array<string>,
  /** Issue body content */
  body?: string,
  /** Issue number that this issue is a duplicate of. Required when state_reason is 'duplicate'. */
  duplicate_of?: number,
  /**
   * Issue field values to set or clear. Each item requires 'field_name' and exactly one of 'value', 'field_option_name', or 'delete: true'.
   */
  issue_fields?: Array<{
      /**
       * Set to true to clear this field's current value on the issue. When false or omitted, this property is ignored. Cannot be true when 'value' or 'field_option_name' is provided.
       */
      delete?: boolean,
      /**
       * Issue field name (case-insensitive). Must match a field returned by list_issue_fields for this repository or its organization.
       */
      field_name: string,
      /**
       * Option name for single-select fields. Validated against the field's options before the API call. Cannot be combined with 'value' or 'delete: true'.
       */
      field_option_name?: string,
      /**
       * Value to set. Use for text, number, and date fields (date as YYYY-MM-DD). For single-select fields, prefer 'field_option_name' so the option is validated before the API call. Cannot be combined with 'field_option_name' or 'delete: true'.
       */
      value?: string | number | boolean,
    }>,
  /** Issue number to update */
  issue_number?: number,
  /** Labels to apply to this issue */
  labels?: Array<string>,
  /**
   * Write operation to perform on a single issue.
   * Options are:
   * - 'create' - creates a new issue.
   * - 'update' - updates an existing issue.
   */
  method: "create" | "update",
  /** Milestone number */
  milestone?: number,
  /** Repository owner */
  owner: string,
  /**
   * Issue number of the parent issue. Only used when method is 'create' and cannot be combined with issue_fields. The new issue is created and attached to this parent in the same operation.
   * @minimum 1
   */
  parent_issue_number?: number,
  /**
   * Repository owner of the parent issue. Must be provided with parent_repo. Omit both to use owner and repo. Only used when method is 'create' and parent_issue_number is provided.
   */
  parent_owner?: string,
  /**
   * Repository name of the parent issue. Must be provided with parent_owner. Omit both to use owner and repo. Only used when method is 'create' and parent_issue_number is provided.
   */
  parent_repo?: string,
  /** Repository name */
  repo: string,
  /** New state */
  state?: "open" | "closed",
  /** Reason for the state change. Ignored unless state is changed. */
  state_reason?: "completed" | "not_planned" | "duplicate",
  /** Issue title */
  title?: string,
  /**
   * Type of this issue. For updates, pass null to remove the current type. Only use if issue types are enabled for this repository. Use list_issue_types to get valid type values for this repository or its owner organization. If the repository doesn't support issue types, omit this parameter.
   */
  type?: string | null,
}): Promise<unknown>"},{"path":"tools.github.search_issues","description":"Search issues using natural-language semantic matching. Best for conceptual or paraphrased queries (e.g. "login fails after password reset"). Already scoped to is:issue.","signature":"tools.github.search_issues({
  /**
   * Subset of fields to return for each issue result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body', 'reactions', and 'labels' in particular drops the largest per-result data.
   */
  fields?: Array<"number" | "title" | "body" | "state" | "state_reason" | "draft" | "locked" | "html_url" | "user" | "author_association" | "labels" | "assignee" | "assignees" | "milestone" | "comments" | "reactions" | "created_at" | "updated_at" | "closed_at" | "closed_by" | "type" | "repository_url" | "pull_request" | "field_values">,
  /** Sort order */
  order?: "asc" | "desc",
  /** Optional repository owner. If provided with repo, only issues for this repository are listed. */
  owner?: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /**
   * The search query, as natural language. When the user gives alternative wordings, include them as plain words rather than joining them with OR.
   */
  query: string,
  /** Optional repository name. If provided with owner, only issues for this repository are listed. */
  repo?: string,
  /** Sort field by number of matches of categories, defaults to best match */
  sort?: "comments" | "reactions" | "reactions-+1" | "reactions--1" | "reactions-smile" | "reactions-thinking_face" | "reactions-heart" | "reactions-tada" | "interactions" | "created" | "updated",
}): Promise<unknown>"},{"path":"tools.github.list_issues","description":"List issues in a GitHub repository. For pagination, use the 'endCursor' from the previous response's 'pageInfo' in the 'after' parameter.","signature":"tools.github.list_issues({
  /** Cursor for pagination. Use the cursor from the previous response. */
  after?: string,
  /** Order direction. If provided, the 'orderBy' also needs to be provided. */
  direction?: "ASC" | "DESC",
  /**
   * Filter by custom issue field values. Each entry takes a field_name and a value; the server looks up the field and coerces the value to its type (single-select option name, text, number, or YYYY-MM-DD date).
   */
  field_filters?: Array<{
      /** Name of the custom field (e.g. "Priority"). Case-insensitive. */
      field_name: string,
      /**
       * Value to filter on. For single-select fields, the option name (e.g. "P1"). For dates, YYYY-MM-DD. For numbers, the numeric value as a string. For text, the text value.
       */
      value: string,
    }>,
  /**
   * Subset of fields to return for each issue. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body' and 'field_values' in particular drops the largest per-result data.
   */
  fields?: Array<"number" | "title" | "body" | "state" | "user" | "labels" | "assignees" | "comments" | "created_at" | "updated_at" | "field_values">,
  /** Filter by labels */
  labels?: Array<string>,
  /** Order issues by field. If provided, the 'direction' also needs to be provided. */
  orderBy?: "CREATED_AT" | "UPDATED_AT" | "COMMENTS",
  /** Repository owner */
  owner: string,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Repository name */
  repo: string,
  /** Filter by date (ISO 8601 timestamp) */
  since?: string,
  /** Filter by state, by default both open and closed issues are returned when not provided */
  state?: "OPEN" | "CLOSED",
}): Promise<unknown>"},{"path":"tools.github.sub_issue_write","description":"Add a sub-issue to a parent issue in a GitHub repository.","signature":"tools.github.sub_issue_write({
  /** The ID of the sub-issue to be prioritized after (either after_id OR before_id should be specified) */
  after_id?: number,
  /** The ID of the sub-issue to be prioritized before (either after_id OR before_id should be specified) */
  before_id?: number,
  /** The number of the parent issue */
  issue_number: number,
  /**
   * The action to perform on a single sub-issue
   * Options are:
   * - 'add' - add a sub-issue to a parent issue in a GitHub repository.
   * - 'remove' - remove a sub-issue from a parent issue in a GitHub repository.
   * - 'reprioritize' - change the order of sub-issues within a parent issue in a GitHub repository. Use either 'after_id' or 'before_id' to specify the new position.
   * Writes issue hierarchy. To move a sub-issue to a new parent, use `add` with `replace_parent=true`; there is no writable parent field.
   */
  method: string,
  /** Repository owner */
  owner: string,
  /** When true, replaces the sub-issue's current parent issue. Use with 'add' method only. */
  replace_parent?: boolean,
  /** Repository name */
  repo: string,
  /** The ID of the sub-issue to add. ID is not the same as issue number */
  sub_issue_id: number,
}): Promise<unknown>"},{"path":"tools.github.list_issue_types","description":"List supported issue types for a repository or its owner organization. When repo is omitted, returns org-level issue types directly.","signature":"tools.github.list_issue_types({
  /** The account owner of the repository or organization. */
  owner: string,
  /**
   * The name of the repository. When provided, returns issue types for this specific repository. When omitted, returns org-level issue types directly.
   */
  repo?: string,
}): Promise<unknown>"},{"path":"tools.github.add_issue_comment","description":"Add a comment and/or reaction to a specific issue or issue comment in a GitHub repository. Use this tool with pull requests as well (in this case pass pull request number as issue_number), but only if user is not asking specifically to add or react to review comments. At least one of body or reaction is required.","signature":"tools.github.add_issue_comment({
  /** Comment content. Required unless reaction is provided. @minLength 1 */
  body?: string,
  /**
   * The numeric ID of the issue or pull request comment to react to. Use this for reactions to comments; omit it to react to the issue or pull request itself. Cannot be combined with body.
   * @integer @minimum 1
   */
  comment_id?: number,
  /** Issue or pull request number to comment on or react to. */
  issue_number: number,
  /** Repository owner */
  owner: string,
  /** Emoji reaction to add. Required unless body is provided. */
  reaction?: "+1" | "-1" | "laugh" | "confused" | "heart" | "hooray" | "rocket" | "eyes",
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.ui_get","description":"Fetch UI data for MCP Apps (labels, assignees, milestones, issue types, branches, issue fields, reviewers).","signature":"tools.github.ui_get({
  /** The type of data to fetch */
  method: "labels" | "assignees" | "milestones" | "issue_types" | "branches" | "issue_fields" | "reviewers",
  /** Repository owner (required for all methods) */
  owner: string,
  /** Repository name (required for labels, assignees, milestones, branches, issue fields, reviewers) */
  repo?: string,
}): Promise<unknown>"},{"path":"tools.github.update_issue_comment","description":"Update the body of an existing issue or pull request conversation comment. This tool cannot update pull request review comments.","signature":"tools.github.update_issue_comment({
  /** New comment content. @minLength 1 */
  body: string,
  /**
   * The numeric ID of the issue or pull request conversation comment to update. Do not use a pull request review comment ID.
   * @integer @minimum 1
   */
  comment_id: number,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.list_issue_fields","description":"List issue fields for a repository or organization. Returns field definitions including name, type (text, number, date, single_select), and for single_select fields the list of valid option names. When repo is omitted, returns org-level fields directly.","signature":"tools.github.list_issue_fields({
  /** The account owner of the repository or organization. The name is not case sensitive. */
  owner: string,
  /**
   * The name of the repository. When provided, returns fields for this specific repository (inherited from its organization). When omitted, returns org-level fields directly.
   */
  repo?: string,
}): Promise<unknown>"},{"path":"tools.github.search_pull_requests","description":"Search for pull requests in GitHub repositories using issues search syntax already scoped to is:pr","signature":"tools.github.search_pull_requests({
  /**
   * Subset of fields to return for each pull request result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body', 'reactions', and 'labels' in particular drops the largest per-result data.
   */
  fields?: Array<"number" | "title" | "body" | "state" | "state_reason" | "draft" | "locked" | "html_url" | "user" | "author_association" | "labels" | "assignee" | "assignees" | "milestone" | "comments" | "reactions" | "created_at" | "updated_at" | "closed_at" | "closed_by" | "pull_request" | "repository_url">,
  /** Sort order */
  order?: "asc" | "desc",
  /** Optional repository owner. If provided with repo, only pull requests for this repository are listed. */
  owner?: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Search query using GitHub pull request search syntax */
  query: string,
  /** Optional repository name. If provided with owner, only pull requests for this repository are listed. */
  repo?: string,
  /** Sort field by number of matches of categories, defaults to best match */
  sort?: "comments" | "reactions" | "reactions-+1" | "reactions--1" | "reactions-smile" | "reactions-thinking_face" | "reactions-heart" | "reactions-tada" | "interactions" | "created" | "updated",
}): Promise<unknown>"},{"path":"tools.github.list_branches","description":"List branches in a GitHub repository","signature":"tools.github.list_branches({
  /** Repository owner */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.list_releases","description":"List releases in a GitHub repository","signature":"tools.github.list_releases({
  /**
   * Subset of fields to return for each release. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body' in particular drops the largest per-release data.
   */
  fields?: Array<"id" | "tag_name" | "name" | "body" | "html_url" | "published_at" | "prerelease" | "draft" | "author">,
  /** Repository owner */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.search_repositories","description":"Find GitHub repositories by name, description, readme, topics, or other metadata. Perfect for discovering projects, finding examples, or locating specific repositories across GitHub.","signature":"tools.github.search_repositories({
  /**
   * Return minimal repository information (default: true). When false, modern clients receive additional curated repository details, not the complete GitHub API object. Legacy clients retain full GitHub API repository objects.
   * @default true
   */
  minimal_output?: boolean,
  /** Sort order */
  order?: "asc" | "desc",
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /**
   * Repository search query. Examples: 'machine learning in:name stars:>1000 language:python', 'topic:react', 'user:facebook'. Supports advanced search syntax for precise filtering.
   */
  query: string,
  /** Sort repositories by field, defaults to best match */
  sort?: "stars" | "forks" | "help-wanted-issues" | "updated",
}): Promise<unknown>"},{"path":"tools.github.delete_file","description":"Delete a file from a GitHub repository","signature":"tools.github.delete_file({
  /** Branch to delete the file from */
  branch: string,
  /** Commit message */
  message: string,
  /** Repository owner (username or organization) */
  owner: string,
  /** Path to the file to delete */
  path: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.list_tags","description":"List git tags in a GitHub repository","signature":"tools.github.list_tags({
  /** Repository owner */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.create_branch","description":"Create a new branch in a GitHub repository","signature":"tools.github.create_branch({
  /** Name for new branch */
  branch: string,
  /** Source branch (defaults to repo default) */
  from_branch?: string,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.search_code","description":"Fast and precise code search across ALL GitHub repositories using GitHub's native search engine. Best for finding exact symbols, functions, classes, or specific code patterns.","signature":"tools.github.search_code({
  /**
   * Subset of fields to return for each code search result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'repository' and 'text_matches' in particular drops the largest per-result data.
   */
  fields?: Array<"name" | "path" | "sha" | "repository" | "text_matches">,
  /** Sort order for results */
  order?: "asc" | "desc",
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /**
   * Search query (GitHub code search REST). Implicit AND between terms; supports `OR`, `NOT`, and `"quoted phrase"` for exact match. Qualifiers: `repo:owner/repo`, `org:`, `user:`, `language:`, `path:dir` (prefix match), `filename:exact.ext`, `extension:`, `in:file`, `in:path`, `size:`, `is:archived`, `is:fork`. Max 256 chars. Examples: `WithContext language:go org:github`; `"package main" repo:o/r`; `func extension:go path:cmd repo:o/r`; `NOT TODO language:go repo:o/r`.
   */
  query: string,
  /** Sort field ('indexed' only) */
  sort?: string,
}): Promise<unknown>"},{"path":"tools.github.get_commit","description":"Get details for a commit from a GitHub repository","signature":"tools.github.get_commit({
  /**
   * Level of detail to include for changed files. "none" omits stats and files entirely. "stats" (default) includes per-file metadata: filename, status, and lines-of-code counts (additions, deletions, changes), with no patch content. "full_patch" additionally includes the unified diff content for each file and can be very large.
   * @default "stats"
   */
  detail?: "none" | "stats" | "full_patch",
  /** Repository owner */
  owner: string,
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /** Repository name */
  repo: string,
  /** Commit SHA, branch name, or tag name */
  sha: string,
}): Promise<unknown>"},{"path":"tools.github.fork_repository","description":"Fork a GitHub repository to your account or specified organization","signature":"tools.github.fork_repository({
  /** Organization to fork to */
  organization?: string,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.search_commits","description":"Search for commits across GitHub repositories using GitHub's commit search syntax. Useful for finding specific changes, authors, or messages across one or many repositories. Searches the default branch only.","signature":"tools.github.search_commits({
  /** Sort order */
  order?: "asc" | "desc",
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /**
   * Commit search query (GitHub commit search REST). Searches commit messages on the default branch only. Scope the search with `repo:owner/repo`, `org:`, or `user:` (queries without a scope qualifier match across all of GitHub and are usually not what you want). Other qualifiers: `author:`, `committer:`, `author-name:`, `committer-name:`, `author-email:`, `committer-email:`, `author-date:`, `committer-date:` (supports `>`, `<`, `>=`, `<=`, and `YYYY-MM-DD..YYYY-MM-DD` ranges), `merge:true|false`, `hash:`, `tree:`, `parent:`, `is:public`. Examples: `repo:owner/repo fix panic`; `org:github author:defunkt committer-date:>=2024-01-01`; `"refactor cache" repo:o/r`; `hash:abc1234 repo:o/r`.
   */
  query: string,
  /** Sort by author or committer date (defaults to best match) */
  sort?: "author-date" | "committer-date",
}): Promise<unknown>"},{"path":"tools.github.get_me","description":"Get details of the authenticated GitHub user. Use this when a request is about the user's own profile for GitHub. Or when information is missing to build other tool calls.","signature":"tools.github.get_me(): Promise<unknown>"},{"path":"tools.github.create_repository","description":"Create a new GitHub repository in your account or specified organization","signature":"tools.github.create_repository({
  /** Initialize with README */
  autoInit?: boolean,
  /** Repository description */
  description?: string,
  /** Repository name */
  name: string,
  /** Organization to create the repository in (omit to create in your personal account) */
  organization?: string,
  /** Whether the repository should be private. Defaults to true (private) when omitted. @default true */
  private?: boolean,
}): Promise<unknown>"},{"path":"tools.github.get_tag","description":"Get details about a specific git tag in a GitHub repository","signature":"tools.github.get_tag({
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
  /** Tag name */
  tag: string,
}): Promise<unknown>"},{"path":"tools.github.push_files","description":"Push multiple files to a GitHub repository in a single commit","signature":"tools.github.push_files({
  /** Branch to push to */
  branch: string,
  /** Array of file objects to push, each object with path (string) and content (string) */
  files: Array<{
      /** file content */
      content: string,
      /** path to the file */
      path: string,
    }>,
  /** Commit message */
  message: string,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.search_users","description":"Find GitHub users by username, real name, or other profile information. Useful for locating developers, contributors, or team members.","signature":"tools.github.search_users({
  /** Sort order */
  order?: "asc" | "desc",
  /** Page number for pagination (min 1). @minimum 1 */
  page?: number,
  /** Results per page for pagination (min 1, max 100). @minimum 1 @maximum 100 */
  perPage?: number,
  /**
   * User search query. Examples: 'john smith', 'location:seattle', 'followers:>100'. Search is automatically scoped to type:user.
   */
  query: string,
  /** Sort users by number of followers or repositories, or when the person joined GitHub. */
  sort?: "followers" | "repositories" | "joined",
}): Promise<unknown>"},{"path":"tools.github.get_latest_release","description":"Get the latest release in a GitHub repository","signature":"tools.github.get_latest_release({
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.merge_pull_request","description":"Merge a pull request in a GitHub repository.","signature":"tools.github.merge_pull_request({
  /** Extra detail for merge commit */
  commit_message?: string,
  /** Title for merge commit */
  commit_title?: string,
  /** The expected SHA of the pull request's HEAD ref */
  expectedHeadSha?: string,
  /** Merge method */
  merge_method?: "merge" | "squash" | "rebase",
  /** Repository owner */
  owner: string,
  /** Pull request number */
  pullNumber: number,
  /** Repository name */
  repo: string,
}): Promise<unknown>"},{"path":"tools.github.create_pull_request","description":"Create a new pull request in a GitHub repository.","signature":"tools.github.create_pull_request({
  /** Branch to merge into */
  base: string,
  /** PR description */
  body?: string,
  /** Create as draft PR */
  draft?: boolean,
  /** Branch containing changes */
  head: string,
  /** Allow maintainer edits */
  maintainer_can_modify?: boolean,
  /** Repository owner */
  owner: string,
  /** Repository name */
  repo: string,
  /** GitHub usernames or ORG/team-slug team reviewers to request reviews from */
  reviewers?: Array<string>,
  /** PR title */
  title: string,
}): Promise<unknown>"},{"path":"tools.github.update_pull_request","description":"Update an existing pull request in a GitHub repository.","signature":"tools.github.update_pull_request({
  /** New base branch name */
  base?: string,
  /** New description */
  body?: string,
  /** Mark pull request as draft (true) or ready for review (false) */
  draft?: boolean,
  /** Allow maintainer edits */
  maintainer_can_modify?: boolean,
  /** Repository owner */
  owner: string,
  /** Pull request number to update */
  pullNumber: number,
  /** Repository name */
  repo: string,
  /** GitHub usernames or ORG/team-slug team reviewers to request reviews from */
  reviewers?: Array<string>,
  /** New state */
  state?: "open" | "closed",
  /** New title */
  title?: string,
}): Promise<unknown>"},{"path":"tools.github.pull_request_read","description":"Get information on a specific pull request in GitHub repository.","signature":"tools.github.pull_request_read({
  /**
   * Cursor for pagination, used only by the get_review_comments method. Pass the endCursor from the previous page's PageInfo to fetch the next page.
   */
  after?: string,
  /**
   * Action to specify what pull request data needs to be retrieved from GitHub.
   * Possible options:
   *  1. get - Get details of a specific pull request.
   *  2. get_diff - Get the diff of a pull request.
