TEST_CASE("TiffImage class") {

  { // jim___ah.tif
    // Dimensions: 664x813
    // Resolution: 300 DPI
    // Bit depth: 1
    // Compression: Uncompressed
    // Resolution unit: 2
    const std::string test_file = "jim___ah.tif";
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    TiffImage image = TiffImage::read(getTestFilePath(test_file));
    std::cout << image << std::endl;

    const auto& ifds = image.ifds();
    CHECK(ifds.size() == 1);

    const auto& entries = ifds[0].entries();
    CHECK(entries.size() == 14);

    #define value_span(type, tag) entries.at(tag).values<type>()
    #define Eq(a, b) std::equal(a.begin(), a.end(), b.begin())

    CHECK(Eq(value_span(uint16_t, Tag::ImageWidth), make_span<uint16_t>({ 664 })));
    CHECK(Eq(value_span(uint16_t, Tag::ImageLength), make_span<uint16_t>({ 813 })));
    CHECK(Eq(value_span(uint16_t, Tag::Compression), make_span<uint16_t>({ 1 })));
    CHECK(Eq(value_span(uint16_t, Tag::PhotometricInterpretation), make_span<uint16_t>({ 0 })));
    CHECK(Eq(value_span(Rational, Tag::XResolution), make_span({ Rational{300, 1} })));
    CHECK(Eq(value_span(Rational, Tag::YResolution), make_span({ Rational{300, 1} })));

    #undef Eq
    #undef value_span

    auto imageData = image.readImageStrips(image.stream(), ifds[0]);
    constexpr size_t expectedImageDataSize = 664 * 813 / 8; // 1 bit per pixel
    size_t actualImageDataSize = 0;
    for (const auto& data : imageData) {
      actualImageDataSize += data.size();
    }
    CHECK(actualImageDataSize == expectedImageDataSize);
  }

  { // jim___ah.tif: using load function
    const std::string test_file = "jim___ah.tif";
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    load(getTestFilePath(test_file),
      [](const TiffImage::Header& header, const TiffImage::IFD& ifd, TiffImage::ImageData imageData) {
        std::cout << "Loaded IFD with " << ifd.entries().size() << " entries." << std::endl;
        std::cout << "Image data size: " << imageData.size() << std::endl;

        const auto& entries = ifd.entries();

        #define value_span(type, tag) entries.at(tag).values<type>()
        #define Eq(a, b) std::equal(a.begin(), a.end(), b.begin())

        CHECK(Eq(value_span(uint16_t, Tag::ImageWidth), make_span<uint16_t>({ 664 })));
        CHECK(Eq(value_span(uint16_t, Tag::ImageLength), make_span<uint16_t>({ 813 })));
        CHECK(Eq(value_span(uint16_t, Tag::Compression), make_span<uint16_t>({ 1 })));
        CHECK(Eq(value_span(uint16_t, Tag::PhotometricInterpretation), make_span<uint16_t>({ 0 })));
        CHECK(Eq(value_span(Rational, Tag::XResolution), make_span({ Rational{300, 1} })));
        CHECK(Eq(value_span(Rational, Tag::YResolution), make_span({ Rational{300, 1} })));

        #undef Eq
        #undef value_span

        constexpr size_t expectedImageDataSize = 664 * 813 / 8; // 1 bit per pixel
        size_t actualImageDataSize = 0;
        for (const auto& data : imageData) { actualImageDataSize += data.size(); }
        CHECK(actualImageDataSize == expectedImageDataSize);
      }
    );
  }

  { // cramps-tile.tif: using load function
    const std::string test_file = "cramps-tile.tif";
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    load(getTestFilePath(test_file),
      [](const TiffImage::Header& header, const TiffImage::IFD& ifd, TiffImage::ImageData imageData) {
        std::cout << "Loaded IFD with " << ifd.entries().size() << " entries." << std::endl;
        std::cout << "Image data size: " << imageData.size() << std::endl;

        const auto& entries = ifd.entries();

        #define value_span(type, tag) entries.at(tag).values<type>()
        #define Eq(a, b) std::equal(a.begin(), a.end(), b.begin())

        CHECK(Eq(value_span(uint16_t, Tag::ImageWidth), make_span<uint16_t>({ 800 })));
        CHECK(Eq(value_span(uint16_t, Tag::ImageLength), make_span<uint16_t>({ 607 })));
        CHECK(Eq(value_span(uint16_t, Tag::Compression), make_span<uint16_t>({ 1 })));
        CHECK(Eq(value_span(uint16_t, Tag::PhotometricInterpretation), make_span<uint16_t>({ 0 })));
        CHECK(Eq(value_span(uint16_t, Tag::TileWidth), make_span<uint16_t>({ 256 })));
        CHECK(Eq(value_span(uint16_t, Tag::TileLength), make_span<uint16_t>({ 256 })));
        CHECK(Eq(value_span(uint16_t, Tag::SamplesPerPixel), make_span<uint16_t>({ 1 })));
        CHECK(Eq(value_span(uint16_t, Tag::BitsPerSample), make_span<uint16_t>({ 8 })));

        #undef Eq
        #undef value_span

        constexpr size_t tilesAcross = (800 + (256 - 1)) / 256;
        constexpr size_t tilesDown = (607 + (256 - 1)) / 256;
        constexpr size_t tilesInImage = tilesAcross * tilesDown;
        CHECK(imageData.size() == tilesInImage);

        constexpr size_t expectedTileSize = 256 * 256;
        for (const auto& tile : imageData) {
          CHECK(tile.size() == expectedTileSize);
        }
      }
    );
  }
}

TEST_CASE("Malformed TIFF input") {

  { // (a) ASCII entry with count == 0
    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8
    writeValue(stream, static_cast<uint16_t>(1), false);                      // 1 entry
    writeValue(stream, static_cast<uint16_t>(Tag::ImageDescription), false);  // Tag
    writeValue(stream, static_cast<uint16_t>(Type::ASCII), false);            // Type
    writeValue(stream, static_cast<uint32_t>(0), false);                      // Count == 0
    writeValue(stream, static_cast<uint32_t>(0), false);                      // Inline value
    writeValue(stream, static_cast<uint32_t>(0), false);                      // Next IFD offset
    CHECK_THROWS_AS(TiffImage::read(stream), std::runtime_error);
  }

  { // (b) Cyclic IFD offset
    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8: 0 entries, next IFD offset points back to itself
    writeValue(stream, static_cast<uint16_t>(0), false);      // 0 entries
    writeValue(stream, static_cast<uint32_t>(8), false);      // Next IFD offset (cyclic)
    CHECK_THROWS_AS(TiffImage::read(stream), std::runtime_error);
  }

  { // (c) Truncated strip: strip data is missing from the stream
    std::vector<TiffImage::IFD::Entry> entries;
    auto addEntry = [&entries](
      uint16_t tag, Type type, uint32_t count,
      const std::vector<uint8_t>& values,
      uint32_t valueOffset = 0, bool mustSwap = false) {
        std::stringstream stream;
        // Write the entry
        write_IFD_entry(
          stream, static_cast<Tag>(tag), type, count,
          reinterpret_cast<const std::byte*>(values.data()),
          valueOffset, mustSwap);
        // Read the entry back
        TiffImage::IFD::Entry entry = TiffImage::IFD::Entry::read(stream, mustSwap);
        // Add the entry to the vector
        entries.push_back(entry);
    };
    // Entries must be sorted in ascending tag order
    addEntry(0x0103, Type::SHORT, 1, { 1 });                  // Compression = none
    addEntry(0x0106, Type::SHORT, 1, { 0 });                  // PhotometricInterpretation = WhiteIsZero
    addEntry(0x0111, Type::LONG, 1, { 100, 0, 0, 0 });        // StripOffsets = 100 (beyond end of stream)
    addEntry(0x0117, Type::LONG, 1, { 232, 3, 0, 0 });        // StripByteCounts = 1000

    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8 (only the IFD; the strip data is not written)
    write_IFD(stream, entries, false);
    writeValue(stream, static_cast<uint32_t>(0), false);      // Next IFD offset
    CHECK_THROWS_AS(
      load(stream, [](auto&&...) { }, LoadParams{}),
      std::runtime_error);
  }

  { // (d) RATIONAL entry with a zero denominator
    std::stringstream stream;
    writeValue(stream, static_cast<uint16_t>(0x4949), false); // "II"
    writeValue(stream, static_cast<uint16_t>(42), false);     // Magic number
    writeValue(stream, static_cast<uint32_t>(8), false);      // First IFD offset
    // IFD at offset 8
    writeValue(stream, static_cast<uint16_t>(1), false);                 // 1 entry
    writeValue(stream, static_cast<uint16_t>(Tag::XResolution), false);  // Tag
    writeValue(stream, static_cast<uint16_t>(Type::RATIONAL), false);    // Type
    writeValue(stream, static_cast<uint32_t>(1), false);                 // Count
    writeValue(stream, static_cast<uint32_t>(26), false);                // Value offset (after the IFD table)
    writeValue(stream, static_cast<uint32_t>(0), false);                 // Next IFD offset (offset 22)
    // RATIONAL value at offset 26: numerator = 300, denominator = 0
    writeValue(stream, static_cast<uint32_t>(300), false);               // Numerator
    writeValue(stream, static_cast<uint32_t>(0), false);                 // Denominator
    // Entry::read does not divide rationals, so reading the image must not throw
    TiffImage image = TiffImage::read(stream);
    REQUIRE(image.ifds().size() == 1);
    CHECK_THROWS_AS(TiffExporter::getIntVec(image.ifds()[0], Tag::XResolution), std::runtime_error);
  }
}

TEST_CASE("LONG ImageWidth fixtures") {

  auto checkFixture = [](const std::string& filename, uint32_t expectedWidth, uint32_t expectedLength) {
    const std::string test_file = filename;
    std::cout << "Test file path: " << getTestFilePath(test_file) << std::endl;
    TiffImage image = TiffImage::read(getTestFilePath(test_file));

    const auto& entries = image.ifds().at(0).entries();

    const auto widthIt = entries.find(Tag::ImageWidth);
    REQUIRE(widthIt != entries.end());
    CHECK(widthIt->second.type() == Type::LONG);
    CHECK(widthIt->second.values<uint32_t>()[0] == expectedWidth);
    // LONG entries do not fit the 16-bit accessor (documents the D6 defect class)
    CHECK_THROWS_AS(widthIt->second.values<uint16_t>(), std::runtime_error);

    const auto lengthIt = entries.find(Tag::ImageLength);
    REQUIRE(lengthIt != entries.end());
    CHECK(lengthIt->second.type() == Type::LONG);
    CHECK(lengthIt->second.values<uint32_t>()[0] == expectedLength);
    CHECK_THROWS_AS(lengthIt->second.values<uint16_t>(), std::runtime_error);
  };

  checkFixture("pc260001.tif", 640, 480);
  checkFixture("smallliz.tif", 160, 160);
}

TEST_CASE("Type::BYTE printed as integer") {

  const std::vector<uint8_t> values{ 0x41 }; // 65 ('A')
  std::stringstream stream;
  write_IFD_entry(
    stream, Tag::ImageWidth, Type::BYTE, 1,
    reinterpret_cast<const std::byte*>(values.data()));

  TiffImage::IFD::Entry entry = TiffImage::IFD::Entry::read(stream, false);

  std::ostringstream ss;
  ss << entry;
  CHECK(ss.str().find("65") != std::string::npos);
  CHECK(ss.str().find("'A'") == std::string::npos);
}

# Changelog

All notable changes to this project will be documented in this file.

The format is based on [Keep a Changelog](https://keepachangelog.com/en/1.1.0/),
and this project adheres to [Semantic Versioning](https://semver.org/spec/v2.0.0.html).

Given a version number MAJOR.MINOR.PATCH, increment the:

    MAJOR version when you make incompatible API changes.
    MINOR version when you add functionality in a backward compatible manner.
    PATCH version when you make backward compatible bug fixes.

## [0.2.0-Unreleased]

### Added

- Code examples
- README now documents which headers are needed and the copy-only
  consumption path (header-only; copy the headers into the project, no build
  step required).
- CMake consumption improvements: added the `TiffCraft::TiffCraft` namespaced
  alias, an installable/exportable target with generated
  `TiffCraftConfig.cmake`/`TiffCraftConfigVersion.cmake` (for `find_package`),
  and a `TIFFCRAFT_BUILD_ALL` option that defaults to `ON` when building
  TiffCraft standalone and to `OFF` when consumed via `FetchContent` or
  `add_subdirectory`.

### Fixed

- `TiffExporter.hpp` no longer includes the umbrella header `TiffCraft.hpp`;
  it now includes `TiffImage.hpp` directly, resolving the include cycle and
  making the exporter header standalone.
- ODR violations in headers: `inline` on `version()`, `readAt()`, `writeAt()`,
  and both `load()` overloads (`TiffImage.hpp`); the six `operator<<` overloads
  moved into `namespace TiffCraft` and marked `inline` (`TiffStdOut.hpp`).
  Note: the stream operators are no longer visible in the global namespace;
  they are found via ADL, which applies to all TiffCraft types.
- Crash/hang fixes for malformed TIFF input: ASCII entry with count 0 no
  longer reads out of bounds (throws `std::runtime_error`); RATIONAL/SRATIONAL
  entries with a zero denominator no longer divide by zero (throws
  `std::runtime_error`); cyclic IFD offsets are detected and rejected (throws
  `std::runtime_error`).
- `readAt()` now detects short reads and throws `std::runtime_error`, so
  truncated strips/tiles no longer silently yield zero-filled buffers.
- `takeImage()` no longer copies instead of moving; it moves the image buffer
  out of the exporter, leaving it empty.
- `TiffExporterAny` now resets its multi-IFD state per IFD; each IFD is
  exported and the last successfully exported image wins (previously later
  IFDs were silently skipped).
- Example `tiff_image` reads `ImageWidth`/`ImageLength` type-agnostically, so
  LONG-typed entries no longer throw.
- README quick-start snippet fixed (removed undeclared `loadParams` argument;
  fixed `iffExporter` typo).
- `Type::BYTE` entries print as integers instead of raw characters.

## [0.1.0]

### Added

- Initial TiffCraft code for loading TIFF images and exporter for bilevel,
  grayscale, palette-color, and RGB images. Compression is not supported.
- Example `tiff_exporter` program to convert TIFF images to PNG 8-bit format.

### Changed

- Moved all headers to `include/tiffcraft`.
